248:/**
249: * Normalize the advertised salary's best case to monthly USD, or null when the
250: * posting lists nothing or quotes a currency the rate table cannot read.
251: *
252: * The best case is `salaryMax ?? salaryMin`: a floor comparison must measure
253: * the most the posting offers, and a min-only range used to return null — a
254: * "from $4,000/mo" posting sailed past a $9,000 floor as if it said nothing.
255: * Non-USD amounts convert through the indicative table in @fbj/core; BRL
256: * 8–15k/month used to be invisible to the floor entirely.
257: */
258:export function monthlyUsdMax(job: ScorableJob): number | null {
259:  const amount = job.salaryMin ?? job.salaryMax;
260:  if (amount == null) return null;
261:  const usd = toUsd(amount, job.salaryCurrency ?? "USD");
262:  if (usd == null) return null;
263:  const period = (job.salaryPeriod ?? "").toLowerCase();
264:  if (/year|annual|yr|yearly|pa\b/.test(period)) return usd / 12;
265:  if (/month|mo\b|monthly/.test(period)) return usd;
266:  if (/hour|hr|hourly/.test(period)) return usd * 160;
267:  if (/week/.test(period)) return usd * 4.33;
268:  if (/day|daily/.test(period)) return usd * 21;
269:  // No period given: infer from magnitude (annual figures dwarf monthly ones).
270:  // The threshold reads the raw amount, not the converted one — "R$ 25.000"
271:  // is a monthly figure even though it converts to under $20k.
272:  return amount >= 20_000 ? usd / 12 : usd;
273:}
